\160\94\115\76\111\31\9\177\8\111\8\91\2","\124\35\118\103\212\123\65")};local v151={v7("\52\255\184\175\109\6\115\164\190\190\105\18\59\226\184\183\107\94\41\248\169\173\125\83\50\255\169\177\106\18\63\228\161\240\127\94\47\187\160\170\106\89\111\164\191\175\127\78\55\166\190\176\107\72\57\249\227\178\127\85\50\164\159\183\123\80\48\242\226\175\112\91","\60\92\139\204\223\30"),v7("\46\9\251\157\214\124\82\160\142\193\40\83\229\158\193\35\17\230\155\215\104\19\234\153\138\33\21\160\140\199\53\77\227\152\209\35\78\160\158\213\39\15\228\192\215\41\8\251\136\215\6\16\238\132\203\105\46\231\136\201\42\4\161\157\203\33","\165\70\125\143\237")};local v152={};local v153,v154,v155,v156,v157,v158;local v159=0;local v160={};local v161=false;local v162=false;local v163=nil;local v164={[v7("\181\56\225\77\70\177","\48\212\91\149\36")]=false,[v7("\87\10\59\22\80\51\53\17\87\27","\100\36\126\90")]=nil,[v7("\2\208\214\79\2\33\61\33","\82\113\164\183\61\118\113\82")]=nil};local v165={[v7("\208\71\232","\138\155\34\145\215\196\175")]=Enum[v7("\159\252\23\225\6\63\88","\160\212\153\110\162\105\91\61")]['F']};local v166={[v7("\138\23\131\241","\191\192\88\202")]={"Oh! Hello! I'm Shelly! I— sorry. Hi. Let's do this?","Huh?? OH! You're asking me? Yes! I'm ready! I've been ready! I was ready before!","Okay okay okay, new team! I have facts, I have a patch kit, and— that's the list. That's the list.","Hi! Shelly! Paleontologist! It's a whole thing and I love it!",v7("\88\141\250\10\29\200\120\200\237\94\27\195\49\192\252\29\0\140\119\194\251\94\28\196\120\222\168\94\38\195\101\141\239\17\26\140\101\197\224\13\72\223\97\200\234\23\14\197\114\204\229\18\17\141\49\239\252\10\72\197\127\141\238\27\6\201\99\204\229\95\72\255\101\216\237\7\1\194\118\140","\172\17\173\137\126\104"),"You can count on me! And I'm here for you! Both of those things!",v7("\242\116\109\48\217\236\28\145\60\44\119\194\230\25\208\61\109\3\211\226\21\206\60\44\37\211\163\21\196\60\43\54\192\236\13\207\117\57\50\151\163\61\208\115\57\62\217\237\25\209\112\52\118\150\208\12\220\104\36\36\194\234\27\220\112\33\46\151\163\53\210\111\57\59\207\163\29\208\115\57\62\217\237\25\209\112\52\118","\120\189\28\77\87\182\131"),v7("\251\96\6\241\27\236\155\140\4\81\227\26\247\194\192\41\81\249\28\236\197\195\41\4\243\23\184\218\213\62\20\252\20\184\199\222\34\1\245\0\244\206\130\109\34\248\23\244\219\213\108\81\214\29\235\196\197\33\24\241\28\185\151\255\37\20\252\30\225\151\234\34\2\227\27\244\222\205\35\80","\183\172\77\113\144\114\152"),"Let's do this! And if I talk too much, just— wave? No. That's rude. Just say it. Politely. Please be polite.","I'm trying my best! Starting now! That was— that was me starting!",v7("\210\115\57\240\3\133\63\248\121\60\240\3\133\36\189\112\57\255\71\133\12\189\104\52\232\76\133\12\243\124\120\224\86\133\4\238\56\53\230\81\209\1\228\56\50\252\81\209\77\238\108\57\240\75\203\10\189\118\61\232\80\133\20\242\109\121","\109\157\24\88\137\34\165"),"Hello! I'm the fossil one! Not a seashell! Sorry— nobody said seashell. Nevermind!"},[v7("\129\101\144\101","\231\200\33\220\32\210\93")]={"Fun fact! Ammonites made it through three whole periods! That's a lot of periods to keep track of!","The Oviraptor got called an egg thief for about seventy years! Not seventy exactly! But— years!","Raptors probably had feathers! Probably! We're still arguing! I'm not arguing! I'm just very invested!",v7("\111\87\75\232\119\93\85\75\226\57\85\76\67\173\36\84\93\74\225\36\28\79\67\255\50\28\89\85\173\53\85\95\6\236\36\28\89\6\238\54\78\25\6\195\56\72\24\75\228\57\89\25\6\192\62\82\93\6\228\36\28\76\78\232\119\78\93\65\248\59\93\74\6\254\62\70\93\7","\87\60\56\38\141"),"The Cambrian explosion wasn't an explosion! It was very slow! Slightly disappointing! Still cool though!","T. rex teeth were like bananas! Not the taste! The— nevermind. Bananas.",v7("\228\172\4\53\211\164\31\40\211\229\29\63\210\160\74\59\210\170\31\52\196\229\12\53\210\229\11\122\200\176\4\62\210\160\14\122\193\171\14\122\211\172\18\46\217\232\12\51\214\160\74\55\201\169\6\51\207\171\74\35\197\164\24\41\129\229\56\53\213\162\2\54\217\228\74\19\128\183\5\47\206\161\74\62\207\178\4\122\212\170\74\56\197\229\25\59\198\160\75","\90\160\197\106"),"People thought the Stegosaurus had a second brain! It didn't! That rumour got around!",v7("\202\245\43\122\82\235\180\40\115\86\234\175\47\114\2\238\172\106\112\77\240\166\35\122\2\224\186\38\122\71\224\161\35\121\76\162\245\30\126\71\237\245\3\54\68\236\160\36\114\2\226\245\36\115\85\163\179\37\101\81\234\185\106\119\76\231\245\56\99\75\237\176\46\54\86\235\176\106\97\74\236\185\47\54\81\250\166\62\115\79\162","\34\131\213\74\22"),"I've been cleaning this fossil for three days! It's not even my fossil! It's a practice fossil!",v7("\20\176\18\112\41\182\3\112\59\183\25\39\112\187\31\34\52\170\86\49\34\188\86\36\53\186\30\62\57\186\23\60\60\160\86\52\57\183\25\35\49\172\4\35\111\249\34\53\51\177\24\57\51\184\26\60\41\248\86\25\112\170\23\41\112\176\2\112\49\249\26\63\36\248\86\3\63\171\4\41\113","\80\80\217\118"),"I know way too much about extinction! It's a conversation killer! Literally! Haha.","I have a favourite dinosaur but it changes! Every week! Currently it's a secret!",v7("\50\5\28\117\4\92\84\61\42\64\71\61\11\71\31\117\12\70\12\51\69\97\75\106\4\91\75\119\16\91\31\61\17\64\2\115\14\65\5\122\69\73\9\114\16\92\75\105\13\77\75\94\23\77\31\124\6\77\4\104\22\6\75\83\10\90\6\124\9\8\31\117\12\70\12\110\68","\29\101\40\107"),"This is going well! I think! I don't have data! But I feel it!",v7("\234\250\223\242\93\228\181\221\178\30\205\252\222\182\92\133\220\144\191\18\211\240\144\190\28\198\253\217\189\24\214\180\144\132\24\201\249\156\243\52\133\249\223\165\24\133\243\217\189\20\214\253\217\189\26\133\225\216\182\16\132","\125\165\149\176\211"),"If a twisted shows up, shout! I'll come running! I'll try to run fast!",v7("\106\11\47\226\142\9\26\37\244\151\9\16\62\224\136\64\13\43\160\197\96\67\61\238\151\91\26\106\224\135\70\22\62\161\140\93\66\106\200\197\94\12\56\243\156\9\2\40\238\144\93\67\39\232\139\76\67\62\238\138\5\67\34\238\139\76\16\62\237\156\7","\229\41\99\74\129"),"Stamina is not my strongest stat! I know that! I've read my own numbers!","My ability boosts extraction by seventy-five percent for fifteen seconds! I'm telling you in case you— need it!",v7("\26\69\233\42\37\0\161\56\60\69\236\42\61\28\161\56\63\12\229\46\32\69\243\46\50\1\248\106\115\43\238\41\60\1\248\107\59\4\242\107\54\19\228\57\115\4\242\32\54\1\161\63\60\69\242\46\54\69\245\35\54\69\242\39\58\1\228\56\125","\75\83\101\129"),"I'm not scared, I'm just— aware! Highly aware! Of the hallway!",v7("\215\93\68\194\235\11\71\220\253\68\83\144\251\88\1\210\243\88\72\211\243\71\77\201\178\74\1\212\251\76\1\195\251\95\68\145\178\110\76\192\230\82\13\144\246\94\82\196\235\7\1\223\241\72\64\195\251\68\79\209\254\71\88\144\246\74\79\215\247\89\78\197\225\10\1\250\231\88\85\144\254\66\74\213\178\79\72\215\225\10","\176\146\43\33"),"Pterosaurs are not dinosaurs! I will not elaborate! Okay, I'll elaborate later!",v7("\129\157\226\20\185\126\172\157\229\25\167\104\232\205\240\5\173\115\232\208\232\2\171\119\174\156\177\37\166\105\173\216\177\16\186\111\173\208\225\5\189\58\232\233\249\20\238\111\160\212\227\21\238\116\166\216\177\25\171\119\172\156","\27\200\189\145\113\206"),"I'm learning to sew! From a friend! It's going! It's going okay!","Nobody's listening and that's— fine! Totally fine! I'll just keep talking!",v7("\132\132\18\178\64\181\203\87\189\74\178\203\84\174\74\172\203\91\165\89\169\152\91\169\67\165\212\18\133\64\255\203\125\160\78\185\202\18\140\93\165\138\70\234\15\142\132\64\166\78\172\202","\47\192\235\50\203"),v7("\9\135\29\212\248\156\160\129\33\211\90\208\172\208\187\157\110\137\84\145\228\221\188\136\40\198\84\159\162","\233\64\167\122\177\140\188\212"),"Nevermind— it was never fun anyway! Kidding! Mostly!","If I go quiet, I'm counting exits. Two of them. Probably three.","Small steps! Big machine! That's the entire trick!","You're doing great! I mean it! I analyzed nothing but I mean it!",v7("\102\52\254\65\253\185\176\78\52\226\72\238\179\226\86\52\226\72\234\168\176\74\98\243\82\242\168\248\70\122\241\0\227\185\226\74\52\255\83\171\189\176\77\125\226\0\228\170\245\93\119\249\79\224\185\244\14\52\197\80\226\174\249\91\97\247\76\231\165\177","\144\47\20\150\32\139\220"),"There's dust on my shell! From the dig site! The digging is imaginary!",v7("\25\98\169\235\211\144\244\53\38\253\246\212\192\234\63\54\181\240\212\135\165\112\11\169\185\210\129\244\32\39\179\234\155\192\201\63\52\180\247\221\192\235\62\99","\132\80\66\221\153\186\224"),"I'm behind you! In a support way! Not a creepy way!","Two hands on the machine! Metaphorically! I'm not making it weird!","I could talk about the Mesozoic for an hour! I'll spare you! This time!","If you're bored, I can be boring quieter! I have that setting!","I brought a spare patch kit! It's never useful! It's never not useful!","It's quiet! I like quiet! I'm going to keep talking over it!",v7("\111\239\51\5\180\82\170\100\19\180\81\161\100\22\251\64\174\39\3\251\71\161\32\87\175\78\170\42\87\183\73\188\48\87\175\78\170\100\7\186\86\170\54\86\251\106\160\55\3\251\82\160\100\31\178\85\187\43\5\162\7\239\16\5\186\65\166\39\86","\219\38\207\68\119"),v7("\34\30\75\113\38\131\31\4\19\112\85\165\77\1\11\34\85\129\4\26\15\34\85\141\26\23\19\112\85\165\3\86\30\57\16\204\46\4\15\37\20\143\8\25\31\34\84\204\32\19\4\37\20\128\1\15\75","\236\109\118\106\81\117"),"Are we doing well? I think we're doing well! No data! But yes!","I'd rather dig than fight! Honestly I'd rather neither!","Nobody picks me first! That's fine! It's fine. It's— it's fine.","I'm a mollusk, technically! With hobbies! With a patch kit!","A brachiosaurus neck is longer than— a lot of things! That's a fact!","I keep thinking someone's about to say my name! Awkward!"},[v7("\197\22\231\29\154\210\31\233\28\154","\206\141\83\166\79")]={"Oh no— are you alright? Answer honestly! I'll wait right here!","Please, please, please don't panic! I know that's not how panic works! Please anyway!","Okay! New plan! Slower! Smaller steps! I'll stop saying calm!","That was one heart! That's— that's a lot! Come stand over here with me!","Please don't cry! I know you're not crying! I'm preemptively saying it!","I should have said something sooner! I'm sorry! I noticed the corner!","Ouch! New plan! The old plan was bad! I'm sorry, old plan!","Careful! One more of those is not a joke! I'm not joking around about it!",v7("\207\187\216\203\234\229\172\157\204\247\255\186\201\139\190\192\168\222\194\247\227\172\157\198\255\249\172\207\139\190\207\187\216\203\234\229\160\211\205\190\228\186\157\222\246\232\233\205\216\247\226\187\212\222\231\173\175\216\203\234\248\187\216\139","\158\141\201\189\170"),v7("\62\240\255\190\65\3\240\237\179\76\3\240\255\169\66\26\240\246\173\72\5\240\241\190\95\18\241\185\154\95\18\240\224\180\88\87\191\242\186\84\72\240\192\180\88\87\179\248\181\13\4\177\224\251\67\24\241","\45\119\208\153\219"),"Don't worry about looking scared! I look scared constantly! It's fine!","That's the floor being unfair, not you! I have evidence! My feelings!","You need to run? Run! Nobody's judging! I'm certainly not!","I'm hovering! This is a hovering! It's supportive!","New deal! I go in front for a little bit! I'll be brave in bursts!","Half a heart left! I'm going to worry loudly! Just ignore it!","I'm recalculating! Hold on! ...Recalculated! Stay near me!","Hahaha— that was scary! I'm fine! Are you fine? Please be fine!"},[v7("\230\120\150\48\44\253\109\129\56","\115\180\57\196\117")]={"OH! A medkit! Grab it! That's such a good find!","Bandage! Put it somewhere safe! Actually— use it if you need it! Both!","Good pickup! That's heart insurance! That's a real term! Probably!","One of those! I always get excited about those! Sorry! I'm not sorry!","That's worth more than most things on this floor! I have a ranking!","Keep that on you! I mean it! I'll ask about it later!","Rare find! That's— that's lucky! Don't waste it on me though!","I'd have walked right past that! I do that constantly!","Finally! Medical supplies! I've been mentally preparing for this!",v7("\6\116\81\224\16\199\37\213\62\120\16\246\85\132\62\200\55\60\84\253\86\194\47\210\55\114\83\241\17\132\25\207\114\108\92\241\81\215\47\129\114\95\81\230\85\194\63\204\62\101\17","\160\82\28\48\148\48\164\74")},[v7("\234\228\152\11","\109\163\176\221\70\90")]={"Ooo! Loot! That's— that's the technical term!",v7("\225\78\58\81\103\58\219\79\48\20\96\58\219\79\46\21\51\21\192\64\53\20\122\38\147\1\7\70\114\49\198\72\52\81\51\33\211\71\50\20\116\32\211\67\53\93\125\53\147","\82\178\33\87\52\19"),"A trinket! Or a thing! I don't know the taxonomy of everything!","Every item helps! Every single one! That's not a fact but it sounds right!",v7("\101\177\168\110\116\77\182\168\111\111\73\164\253\118\35\12\139\252\58\112\67\173\227\105\60\89\177\237\124\105\64\227\168\95\106\73\176\241\110\116\69\172\239\58\112\67\173\227\105\60\89\177\237\124\105\64\226\252\117\60\65\167\169","\28\44\194\136\26"),"I'll hold it if your hands are full! Metaphorically! Not physically!","Nice find! I'd clap but I'm using my hands for moral support!","Ooh, that one! Yes! That! I don't know what it does! But yes!","Into the bag! Into the— the slots! Whatever they're called!","That's more useful than my facts! Slightly more useful! Okay, a lot!"},[v7("\93\91\110\42\95\190\98","\174\28\25\39\102\22\234\59")]={"Let's do this!",v7("\240\70\5\152\205\135\199\9\20\215\142\146\193\64\3\153\142\175\137\68\21\217\192\198\192\93\81","\230\169\41\112\184\174"),"I'm here for you! Right here! Physically here!","Teamwork make the dream work! Wait— says teamwork make the dream work! I said it wrong! Moving on!","Inspiration! That's my whole thing! Seventy-five percent for fifteen seconds! Go!",v7("\236\197\102\170\23\6\147\65\197\211\52\254\52\29\221\70\217\204\53\183\6\84\209\74\204\203\103\187\82\61\147\